import{_ as a,k as i,a6 as s,j as l}from"./chunks/framework.W_BvR9CP.js";const g=JSON.parse('{"title":"v1.41.0","description":"The changelog for v1.41.0.","frontmatter":{"title":"v1.41.0","page_title":"v1.41.0 Changelog","description":"The changelog for v1.41.0.","category":"Releases","mentions":["Andexter8"]},"headers":[{"level":2,"title":"Changes","slug":"changes","link":"#changes","children":[]},{"level":2,"title":"Fixes","slug":"fixes","link":"#fixes","children":[]},{"level":2,"title":"Technical Additions","slug":"technical-additions","link":"#technical-additions","children":[{"level":3,"title":"API","slug":"api","link":"#api","children":[]},{"level":3,"title":"Debugging","slug":"debugging","link":"#debugging","children":[]}]},{"level":2,"title":"Technical Changes","slug":"technical-changes","link":"#technical-changes","children":[]},{"level":2,"title":"Technical Fixes","slug":"technical-fixes","link":"#technical-fixes","children":[{"level":3,"title":"API","slug":"api-1","link":"#api-1","children":[]}]}],"relativePath":"changelogs/v1.41.0.md","filePath":"changelogs/v1.41.0.md"}'),t={name:"changelogs/v1.41.0.md"};function n(o,e,d,c,h,r){return l(),i("div",null,e[0]||(e[0]=[s('<p><strong>Updated the add-on to 1.21.120!</strong></p><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><ul><li>The <code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/randommap</span></code> loot table now only gives map types that are actually supported by the game.</li><li>The <code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/endcity</span></code> now has a default name of <code class="shiki"><span>§r§fEnd City Explorer Map</span></code> instead of just being called <code class="shiki"><span>Map 0</span></code>.</li><li>The following loot tables no longer have custom names and instead use their vanilla names: <ul><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/jungle_template</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/swamp_hut</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/trial_chambers</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/village_desert</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/village_plains</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/village_savanna</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/village_snowy</span></code></li><li><code class="shiki"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">loot_tables/maps/andexdb/village_taiga</span></code></li></ul></li><li>Updated the recipes for the <a href="./../items/enchantment-transfer-smithing-template.html">Enchantment Transfer Smithing Template</a> (this should fix a few content log errors and allow enchanting newer items).</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><ul><li>Fixed a content log error relating to there being a comment in an <code class="shiki"><span>.mcfunction</span></code> file which was not allowed.</li><li>Fixed a bug where the Manage Server Shops menu had incorrect button mappings, resulting in different buttons than the one you clicked being pressed or errors.</li></ul><h2 id="technical-additions" tabindex="-1">Technical Additions <a class="header-anchor" href="#technical-additions" aria-label="Permalink to &quot;Technical Additions&quot;">​</a></h2><h3 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li>The following modules will now be automatically imported into the <a href="https://api.8crafter.com/andexdb/v1.41.0/functions/Globals.modules.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">modules</span></code></a> namespace if they are added into the <code class="shiki"><span>manifest.json</span></code>: <ul><li><code class="shiki"><span>@minecraft/server-net</span></code></li><li><code class="shiki"><span>@minecraft/server-editor</span></code><ul><li>The following modules will also be imported if <code class="shiki"><span>@minecraft/server-editor</span></code> is added to the <code class="shiki"><span>manifest.json</span></code>: <ul><li><code class="shiki"><span>@minecraft/server-editor-bindings</span></code></li><li><code class="shiki"><span>@minecraft/server-editor-private-bindings</span></code></li></ul></li></ul></li><li><code class="shiki"><span>@minecraft/debug-utilities</span></code></li><li><code class="shiki"><span>@minecraft/diagnostics</span></code></li></ul></li></ul><h3 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h3><ul><li>The startup time console log now also includes the total startup time (pre-startup time + startup time), pre-startup time, and exiting early-execution delay, instead of just the startup time.</li></ul><h2 id="technical-changes" tabindex="-1">Technical Changes <a class="header-anchor" href="#technical-changes" aria-label="Permalink to &quot;Technical Changes&quot;">​</a></h2><ul><li>Updated the <a href="https://api.8crafter.com/andexdb/v1.41.0/modules/_minecraft_vanilla-data.html" target="_blank" rel="noreferrer"><code class="shiki"><span>@minecraft/vanilla-data</span></code></a> module from <code class="shiki"><span>v1.21.110</span></code> to <code class="shiki"><span>v1.21.120</span></code>.</li></ul><h2 id="technical-fixes" tabindex="-1">Technical Fixes <a class="header-anchor" href="#technical-fixes" aria-label="Permalink to &quot;Technical Fixes&quot;">​</a></h2><h3 id="api-1" tabindex="-1">API <a class="header-anchor" href="#api-1" aria-label="Permalink to &quot;API&quot;">​</a></h3><ul><li>Fixed a bug where the <a href="https://api.8crafter.com/andexdb/v1.41.0/functions/Globals.twoWayModulo.html" target="_blank" rel="noreferrer"><code class="shiki"><span style="--shiki-light:#001080;--shiki-dark:#9CDCFE;">twoWayModulo</span></code></a> function would return the modulus instead of 0 when the number was negative and a multiple of the modulus.</li></ul>',15)]))}const u=a(t,[["render",n]]);export{g as __pageData,u as default};
